#!/usr/bin/env python3
"""Independent synthetic S6c purpose vectors, not diameterkit-generated bytes."""
import hashlib,json,struct,runpy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'testdata/codec'
f=runpy.run_path(str(Path(__file__).with_name('router-alert-fixtures.py')));avp,fields,frame=(f[k] for k in ('avp','fields','frame'))
def main():
 r=bytes.fromhex((D/'v-srr-01.hex').read_text());a=bytes.fromhex((D/'v-sra-01.hex').read_text());rf=fields(r[20:]);af=fields(a[20:]);cases={}
 cases['router-r']=r;cases['mcc-r']=frame(r[:20],rf+[(3311,10415,192,struct.pack('!i',1))])
 for n,v in [('only-imsi-r',0),('reserved-r',2),('negative-r',-1)]:cases[n]=frame(r[:20],rf+[(3311,10415,192,struct.pack('!i',v))])
 cases['duplicate-purpose-r']=frame(r[:20],fields(cases['mcc-r'][20:])+[(3311,10415,192,struct.pack('!i',1))])
 cases['short-purpose-r']=frame(r[:20],rf+[(3311,10415,192,b'\0\0\1')])
 for n,value,node in [('router-a',b'route-token-76',True),('numeric-a',b'001010123456789',True),('unicode-a','令牌-é'.encode(),True),('max-a',b'x'*256,True),('long-a',b'x'*257,True),('nul-a',b'a\0b',True),('empty-a',b'',True),('utf8-a',b'\xff',True),('router-nonode',b'route-token-76',False),('mcc-a',b'001010000000000',False),('mcc-node-a',b'001010000000000',True),('mnc3-a',b'001001000000000',False),('prefix-only-a',b'00101',False),('wrong-prefix-a',b'999990000000000',False),('mcc-short-a',b'001010',False)]:
  cases[n]=frame(a[:20],[(c,v,f,value if c==1 else d) for c,v,f,d in af if node or c!=2401])
 cases['missing-name-a']=frame(a[:20],[x for x in af if x[0]!=1])
 cases['duplicate-name-a']=frame(a[:20],af+[(1,0,64,b'route-token-76')])
 for n,code,error in [('failure',5012,False),('e',3004,True)]:
  h=bytearray(a[:20]);h[4]=0x60 if error else 0x40
  cases[n]=frame(h,[(c,v,f,struct.pack('!I',code) if c==268 else d) for c,v,f,d in af if c not in (1,2401)])
 h=a[:20];cases['absent-a']=frame(h,[x for x in af if x[0] not in (1,2401,268)]+[(297,0,64,avp(266,struct.pack('!I',10415))+avp(298,struct.pack('!I',5550)))])
 manifest=json.loads((D/'manifest.json').read_text());manifest=[x for x in manifest if not x['file'].startswith('b76-')]
 for n,b in cases.items():
  name='b76-routing-'+n+'.hex';(D/name).write_text(b.hex()+'\n');manifest.append(dict(file=name,bytes=len(b),sha256=hashlib.sha256(b).hexdigest(),source='spec/batch-76.md',provenance='Independent Python AVP assembly from v-srr-01/v-sra-01; synthetic, not captured'))
 (D/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(len(cases),'new;',len(manifest),'total')
if __name__=='__main__':main()
